import{z as i,x as d,o as n,c as D,q as r,j as o,D as e,d as a,s,S as t,b as B}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"随机数","description":"","frontmatter":{"title":"随机数","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ce-randomness.md","filePath":"cs/ce-randomness.md","lastUpdated":1791413859000}'),l={name:"cs/ce-randomness.md"};function c(p,E,F,S,C,R){const A=d("Mermaid");return n(),D("div",null,[E[2]||(E[2]=r('<h1 id="随机数" tabindex="-1">随机数 <a class="header-anchor" href="#随机数" aria-label="Permalink to &quot;随机数&quot;">​</a></h1><div class="epigraph"><p>密码学里一切「不可预测」的承诺，最终都落到一个数上：熵不够，前面全部的合同都是在拿确定性的原料签不确定性的单。</p><footer>—— 据 RFC 4086；NIST SP 800-90A；Ferguson, Schneier and Kohno, *Cryptography Engineering* 整理</footer></div><p><a href="/cs/ce-side-channels">上一课</a>把实现层的泄露口收到常量时间。本课回到更底层的原料：密钥、nonce、盐、\\(k\\)，全都要求「攻击者猜不到」，而机器是确定性设备，不会自己产出意外。<a href="/cs/csprng">CSPRNG</a>已给过抗预测与抗回溯的目标定义；<a href="/cs/ecdsa-eddsa">ECDSA / EdDSA</a>的 \\(k\\) 复用事件刚演示过弱随机的代价。缺口是<strong>工程链条</strong>：熵从哪来、怎么烧成 DRBG、fork 与虚机会把状态怎么弄坏、nonce 的两个合同为何不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机数事故的历史几乎是同一句话的重复：「熵源看似有，实则可猜」。1996 年 Netscape 的 SSL 种子取自时间与进程号，搜索空间被压到分钟级暴力；2008 年 Debian 打包脚本误删两行，OpenSSL 的种子只剩进程号，全网密钥塌缩到 32768 种；2013 年 Android 的 SecureRandom 实现缺陷让比特币签名重复 \\(k\\)，钱包当场被洗。三案都不是「算法选错」，而是同一层：确定性机器上，不可预测性必须显式制造。缺口是把制造流程钉成组件：熵源（物理噪声、硬件 RNG、事件计时抖动）→ DRBG（把种子确定性扩张成无限流）→ 使用纪律（按用途分合同）。<span class="marginnote">「DRBG」（确定性随机比特生成器）可以类比成榨汁机：熵源给的种子是那一小口不可预测的「原液」，DRBG 把它确定性拉长成无限杯「果汁」。风味全由原液决定——原液本身可猜（熵不够），后面产出再多比特都是假随机，Debian 与 Netscape 两案坏的都是原液这一步。</span></p><h3 id="两个-nonce-合同" tabindex="-1">两个 nonce 合同 <a class="header-anchor" href="#两个-nonce-合同" aria-label="Permalink to &quot;两个 nonce 合同&quot;">​</a></h3><p>同名叫 nonce，合同不同。加密侧（CTR、GCM）的 nonce 要求<strong>唯一但可以公开</strong>：计数器即可，秘密性无关紧要。签名侧（ECDSA 的 \\(k\\)、EdDSA 的派生种子）的 nonce 要求<strong>不可预测且一次性</strong>：必须是 CSPRNG 输出或从密钥确定性派生，泄露即私钥。把签名 nonce 当计数器编，等于把私钥按序号公开——两套合同混用是工程里真实发生过的错误。<span class="marginnote">常见误区：「都是随机数，随便用」。签名侧的惩罚可以代数上看：同一个 \\(k\\) 签两条消息，两条签名的 \\(r\\) 相同立刻露馅，两式相减就能解出 \\(k\\)，而 \\(k\\) 一到手私钥一步就解出来——2013 年 Android 比特币钱包正是这样被洗的。加密侧的 nonce 却只要不重复就行，公开无妨：两套要求长得像，后果天差地别。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程口径按链条走。熵源：优先硬件 RNG（RDRAND/RDSEED 一类）但<strong>不单独信任</strong>，与系统事件（中断计时、设备延迟）混合；熵估计交给标准化健康检查（SP 800-90B 口径），不做手工估计。DRBG：用系统级 CSPRNG（Linux 的 getrandom(2)、/dev/urandom），不自建；自建也只选标准化构造（CTR_DRBG/HMAC_DRBG）并按周期重播种。进程安全：fork 复制父进程的 DRBG 状态，子进程必须立即重播种；虚机快照回滚同理，恢复点之后的输出可能整段重复，这是云环境真实的事故源。使用纪律：密钥与 nonce 各自过 KDF 域分离；盐公开、\\(k\\) 保密，按上一段的两套合同分发。</p>',9)),(n(),o(t,null,{default:e(()=>[s(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENT%5B%22%E7%86%B5%E6%BA%90%EF%BC%9A%E7%A1%AC%E4%BB%B6%20RNG%20%2B%20%E4%BA%8B%E4%BB%B6%E6%8A%96%E5%8A%A8%22%5D%20--%3E%20MIX%5B%22%E5%A4%9A%E6%BA%90%E6%B7%B7%E5%90%88%E4%B8%8E%E5%81%A5%E5%BA%B7%E6%A3%80%E6%9F%A5%22%5D%0A%20%20MIX%20--%3E%20DRBG%5B%22%E7%B3%BB%E7%BB%9F%20CSPRNG%EF%BC%88getrandom%20%2F%20urandom%EF%BC%89%22%5D%0A%20%20DRBG%20--%3E%20K1%5B%22%E5%AF%86%E9%92%A5%EF%BC%9AKDF%20%E5%9F%9F%E5%88%86%E7%A6%BB%22%5D%0A%20%20DRBG%20--%3E%20K2%5B%22%E5%8A%A0%E5%AF%86%20nonce%EF%BC%9A%E8%AE%A1%E6%95%B0%E5%99%A8%E6%88%96%20CSPRNG%22%5D%0A%20%20DRBG%20--%3E%20K3%5B%22%E7%AD%BE%E5%90%8D%20k%EF%BC%9ACSPRNG%20%E6%88%96%E7%A1%AE%E5%AE%9A%E6%80%A7%E6%B4%BE%E7%94%9F%22%5D%0A%20%20FORK%5B%22fork%20%2F%20%E5%BF%AB%E7%85%A7%E5%9B%9E%E6%BB%9A%22%5D%20--%3E%20ST%5B%22%E7%8A%B6%E6%80%81%E8%A2%AB%E5%A4%8D%E5%88%B6%E6%88%96%E5%9B%9E%E9%80%80%22%5D%0A%20%20ST%20--%3E%20RS%5B%22%E5%AD%90%E8%BF%9B%E7%A8%8B%20%2F%20%E6%81%A2%E5%A4%8D%E7%82%B9%E7%AB%8B%E5%8D%B3%E9%87%8D%E6%92%AD%E7%A7%8D%22%5D%0A%20%20WEAK%5B%22%E7%A7%8D%E5%AD%90%E5%8F%AF%E7%8C%9C%22%5D%20--%3E%20PRED%5B%22Debian%202008%EF%BC%9A32768%20%E7%A7%8D%E5%AF%86%E9%92%A5%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("DRBG 为什么敢把 256 位种子拉成无限流？因为底层是 PRF 的安全归约：不知道状态则输出不可区分于均匀——这正是"),B("a",{href:"/cs/one-time-pad-perfect-secrecy"},"一次一密与完美保密"),a("之后「用 PRG 换钥匙长度」的同一笔账。但归约不覆盖两类现实失败：种子本身可猜（熵估计错），状态可回退（fork、快照、克隆）。前者靠 SP 800-90B 的健康检查与多源混合兜底；后者的通用解是「重播种加单调计数」，内核在 fork 与虚机恢复路径上补种的做法即是此理。回溯抵抗为什么重要：会话密钥要在密钥文件被读走之后仍然保密，靠的就是 DRBG 的前向安全——拿到现在推不出过去；重播种的节奏就是在为这条性质付账。")],-1)),(n(),o(t,null,{default:e(()=>[s(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%88%B6%E8%BF%9B%E7%A8%8B%EF%BC%9ADRBG%20%E7%8A%B6%E6%80%81%20S%22%5D%20--%3E%20F%5B%22fork%20%E5%8F%91%E7%94%9F%22%5D%0A%20%20F%20--%3E%20C%5B%22%E5%AD%90%E8%BF%9B%E7%A8%8B%E7%BB%A7%E6%89%BF%E5%90%8C%E4%B8%80%E4%B8%AA%20S%22%5D%0A%20%20C%20--%3E%20O1%5B%22%E5%AD%90%E8%BF%9B%E7%A8%8B%E5%8F%96%E4%B8%8B%E4%B8%80%E5%9D%97%E8%BE%93%E5%87%BA%EF%BC%9AX%22%5D%0A%20%20P%20--%3E%20O2%5B%22%E7%88%B6%E8%BF%9B%E7%A8%8B%E5%8F%96%E4%B8%8B%E4%B8%80%E5%9D%97%E8%BE%93%E5%87%BA%EF%BC%9A%E4%B9%9F%E6%98%AF%20X%22%5D%0A%20%20O1%20--%3E%20CLASH%5B%22%E4%B8%A4%E8%BF%9B%E7%A8%8B%E4%BA%A7%E5%87%BA%E7%9B%B8%E5%90%8C%E7%9A%84%E5%AF%86%E9%92%A5%E4%B8%8E%20nonce%22%5D%0A%20%20CLASH%20--%3E%20FIX%5B%22%E5%AD%90%E8%BF%9B%E7%A8%8B%E7%AB%8B%E5%8D%B3%E9%87%8D%E6%92%AD%E7%A7%8D%EF%BC%9A%E7%8A%B6%E6%80%81%E6%8D%A2%E6%88%90%20S'%22%5D%0A%20%20FIX%20--%3E%20SAFE%5B%22%E6%AD%A4%E5%90%8E%E4%B8%A4%E8%BE%B9%E8%BE%93%E5%87%BA%E5%88%86%E9%81%93%E6%89%AC%E9%95%B3%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">这张图专门回答「fork 为什么是随机数的事故源」：fork 不偷不走，只是把状态原样复印一份，于是两个进程像共用一本密码本的两个人，各自「随机」出的却是同一串数。云与容器环境里 fork、快照回滚天天发生，这就是「子进程先重播种再干活」被写进系统调用约定的原因。</span></p><p><span class="marginnote">Debian 2008 的量级：被删的两行让种子池只剩进程号一个变量，密钥空间塌到 \\(2^{15}\\)，漏洞公开后全网批量重签。同年前后，PS3 的静态 \\(k\\) 从另一条线击穿签名——可预测的熵与重复的 nonce 死法同源：确定性原料冒充随机性。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开熵的物理来源（量子噪声、热噪声采集电路）与形式化熵理论；也不重讲 CSPRNG 的目标定义（见 <a href="/cs/csprng">CSPRNG</a>）。后量子迁移不改变本课任何结论——ML-KEM 的密钥生成同样吃 CSPRNG，格参数对低熵种子更敏感的讨论是前沿课的缺口。签名侧确定性派生（RFC 6979、Ed25519）把在线随机需求降为零，但不取消密钥生成时对熵的需求——<a href="/cs/ecdsa-eddsa">ECDSA / EdDSA</a>已钉过这条边界，不重复。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>随机数事故同源：确定性原料冒充随机性；Netscape、Debian、Android 三案同一句诊断。</li><li>链条三件：多源混合的熵、标准化 DRBG、按用途的使用纪律；手工熵估计一律拒绝。</li><li>fork 与快照回滚复制或回退状态，子进程与恢复点必须立即重播种。</li><li>nonce 两合同：加密侧唯一可公开，签名侧不可预测且一次性。</li><li>出处：RFC 4086；NIST SP 800-90A/90B；Ferguson, Schneier and Kohno；对照 Debian OpenSSL 2008 事件。</li></ul>',6))])}const f=i(l,[["render",c]]);export{m as __pageData,f as default};
